def restore_mt_moon_text(path, source):
    if str(path) != "src/data/wild_encounters.json":
        return source
    for label, original in ORIGINAL_MT_MOON.items():
        marker = '"base_label": "' + label + '"'
        pos = source.index('"mons": [', source.index(marker))
        current = BALANCED_MT_MOON[label]
        assert source[pos:pos+len(current)] == current, label
        source = source[:pos] + original + source[pos+len(current):]
    return source

def prior_mt_moon_source(path):
    return restore_mt_moon_text(path, prior_viridian_forest_source(path).decode("utf-8")).encode("utf-8")

def restore_prior_mt_moon_text(path, source):
    return restore_mt_moon_text(path, restore_prior_viridian_forest_text(path, source))
